// src/pages/Register/RegisterPage.jsx
import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import { register as apiRegister } from "../../services/authService";
import "../../styles/components.css";

export default function RegisterPage() {
  const [form, setForm]       = useState({ username:"", name:"", email:"", password:"", confirm:"" });
  const [error, setError]     = useState("");
  const [loading, setLoading] = useState(false);
  const { login }             = useAuth();
  const navigate              = useNavigate();

  function handleChange(e) {
    setForm((p) => ({ ...p, [e.target.name]: e.target.value }));
    setError("");
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!form.username||!form.name||!form.email||!form.password||!form.confirm){setError("Please fill in all fields");return;}
    if (form.password.length<6){setError("Password must be at least 6 characters");return;}
    if (form.password!==form.confirm){setError("Passwords do not match");return;}
    setLoading(true);
    try {
      const res = await apiRegister(form);
      login(res.data.user, res.data.token);
      navigate("/upload-photo");
    } catch(err) {
      const errs = err.response?.data?.errors;
      if (errs) {
        const first = Object.values(errs)[0];
        setError(Array.isArray(first) ? first[0] : first);
      } else {
        setError(err.response?.data?.message || "An error occurred, please try again");
      }
    } finally { setLoading(false); }
  }

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">
          <div className="auth-logo-icon"><svg width="20" height="20" fill="white" viewBox="0 0 24 24"><path d="M4 4h16v16H4V4zm2 2v12h12V6H6zm2 2h8v2H8V8zm0 4h5v2H8v-2z"/></svg></div>
          <span className="auth-logo-text">Nashr</span>
        </div>
        <h1 className="auth-title">Create a new account</h1>
        <p className="auth-subtitle">Join the reading community and start your journey</p>
        {error && <div className="alert alert-error">{error}</div>}
        <form onSubmit={handleSubmit}>
          <div className="form-group"><label className="form-label">Username *</label><input className="form-input" name="username" placeholder="Example: bookworm99" value={form.username} onChange={handleChange} /></div>
          <div className="form-group"><label className="form-label">Full Name *</label><input className="form-input" name="name" placeholder="Your real name" value={form.name} onChange={handleChange} /></div>
          <div className="form-group"><label className="form-label">Email *</label><input className="form-input" name="email" type="email" placeholder="example@email.com" value={form.email} onChange={handleChange} /></div>
          <div className="form-group"><label className="form-label">Password *</label><input className="form-input" name="password" type="password" placeholder="6 characters minimum" value={form.password} onChange={handleChange} /></div>
          <div className="form-group"><label className="form-label">Confirm Password *</label><input className="form-input" name="confirm" type="password" placeholder="Re-enter your password" value={form.confirm} onChange={handleChange} /></div>
          <button type="submit" className="btn btn-primary btn-full" disabled={loading}>{loading?"Creating account...":"Create Account"}</button>
        </form>
        <div className="auth-footer">Already have an account? <Link to="/login">Log in</Link></div>
      </div>
    </div>
  );
}
